142	
143	export type DnsRecord = {
144	  id: number;
145	  host: string; // "" = apex
146	  type: string;
147	  answer: string;
148	  ttl: number;
149	  priority?: number;
150	};
151	
152	export async function listRecords(domain: string): Promise<DnsRecord[]> {
153	  const json = await nc("GET", `/v4/domains/${encodeURIComponent(domain)}/records`);
154	  return (json.records ?? []).map((r: any) => ({
155	    id: r.id,
156	    host: r.host ?? "",
157	    type: r.type,
158	    answer: r.answer,
159	    ttl: r.ttl ?? 300,
160	    priority: r.priority,
161	  }));
162	}
163	
164	export async function addRecord(
165	  domain: string,
166	  rec: { host: string; type: string; answer: string; ttl?: number; priority?: number }
167	): Promise<void> {
168	  await nc("POST", `/v4/domains/${encodeURIComponent(domain)}/records`, {
169	    host: rec.host,
170	    type: rec.type,
171	    answer: rec.answer,
172	    ttl: rec.ttl ?? 300,
173	    ...(rec.priority !== undefined ? { priority: rec.priority } : {}),
174	  });
175	}
176	
177	export async function deleteRecord(domain: string, id: number): Promise<void> {
178	  await nc("DELETE", `/v4/domains/${encodeURIComponent(domain)}/records/${id}`);
179	}
180	
181	/** Read-only view used by the DNS UI: apex host shown as "@". */
182	export type DnsHost = { name: string; type: string; address: string; ttl: number; mxPref?: number };
183	
184	export async function getDnsHosts(domain: string): Promise<DnsHost[]> {
185	  const recs = await listRecords(domain);
186	  return recs.map((r) => ({
187	    name: r.host === "" ? "@" : r.host,
188	    type: r.type,
189	    address: r.answer,
190	    ttl: r.ttl,
191	    mxPref: r.priority,
192	  }));
193	}
