3	import { useState, type ReactNode } from "react";
4	
5	const TABS = [
6	  "Overview",
7	  "Metrics",
8	  "Console",
9	  "Snapshots",
10	  "Backups",
11	  "Networking",
12	  "Resize",
13	  "Activity",
14	] as const;
