16	export function ServerTabs({
17	  initialTab,
18	  overview,
19	  metrics,
20	  console: consolePanel,
21	  snapshots,
22	  backups,
23	  networking,
24	  resize,
25	  activity,
26	}: {
27	  initialTab?: string;
28	  overview: ReactNode;
29	  metrics: ReactNode;
30	  console: ReactNode;
31	  snapshots: ReactNode;
32	  backups: ReactNode;
33	  networking: ReactNode;
34	  resize: ReactNode;
35	  activity: ReactNode;
36	}) {
37	  const keys = TABS.map((t) => t.toLowerCase());
38	  const [tab, setTab] = useState<string>(
39	    initialTab && keys.includes(initialTab.toLowerCase()) ? initialTab.toLowerCase() : "overview"
40	  );
41	
42	  const panels: Record<string, ReactNode> = {
43	    overview,
44	    metrics,
45	    console: consolePanel,
46	    snapshots,
47	    backups,
48	    networking,
49	    resize,
50	    activity,
51	  };
52	
53	  return (
54	    <div>
55	      <div className="mb-6 flex gap-1 overflow-x-auto rounded-2xl border border-white/[0.06] bg-navy-900/70 p-1 backdrop-blur-md">
56	        {TABS.map((t) => {
57	          const k = t.toLowerCase();
58	          const active = tab === k;
59	          return (
60	            <button
61	              key={k}
62	              type="button"
63	              onClick={() => {
64	                setTab(k);
65	                window.history.replaceState(null, "", `?tab=${k}`);
66	              }}
67	              className={`whitespace-nowrap rounded-xl px-4 py-2 text-sm font-medium transition-colors ${
68	                active
69	                  ? "bg-gradient-to-r from-accent-blue/90 to-brand-500/90 text-white shadow-[0_4px_16px_-6px_rgb(111_71_245_/_0.6)]"
70	                  : "text-slate-400 hover:bg-white/[0.05] hover:text-white"
71	              }`}
72	            >
73	              {t}
74	            </button>
75	          );
76	        })}
77	      </div>
78	      <div className="animate-fade-up">{panels[tab]}</div>
79	    </div>
80	  );
81	}
