40	  const { user, server } = await ownedServer(serverId);
41	  const clean = name.replace(/[^a-zA-Z0-9_]/g, "").slice(0, 40);
42	  if (clean.length < 2) return { error: "Snapshot name: letters, digits, underscores (min 2)." };
43	  if (!server.vmid || !["RUNNING", "STOPPED"].includes(server.status)) {
44	    return { error: "Server must be running or stopped." };
45	  }
46	  const res = await queueJob(serverId, "SNAPSHOT_CREATE", { name: clean });
