import { NextRequest, NextResponse } from "next/server";
import { db } from "@/lib/db";
import { currentUser } from "@/lib/auth";
import { vmRrd, nodeRrd } from "@/lib/proxmox";

export async function GET(req: NextRequest) {
  const user = await currentUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });

  const timeframe = ["hour", "day", "week", "month"].includes(req.nextUrl.searchParams.get("tf") ?? "")
    ? req.nextUrl.searchParams.get("tf")!
    : "hour";

  const serverId = req.nextUrl.searchParams.get("serverId");
  try {
    if (serverId) {
      const server = await db.server.findUnique({ where: { id: serverId } });
      if (!server || (server.userId !== user.id && user.role !== "ADMIN") || !server.vmid) {
        return NextResponse.json({ error: "not found" }, { status: 404 });
      }
      const data = await vmRrd(server.vmid, timeframe);
      return NextResponse.json({ data });
    }
    if (user.role !== "ADMIN") return NextResponse.json({ error: "forbidden" }, { status: 403 });
    const data = await nodeRrd(timeframe);
    return NextResponse.json({ data });
  } catch {
    return NextResponse.json({ data: [] });
  }
}

