/**
 * Read-only helper for per-server disk time-series from Proxmox RRD.
 * Kept out of "use server" files so it can be imported by the API route.
 * Uses the node-aware pveFor() when the server is pinned to a Node row,
 * otherwise falls back to the default single-node client.
 */
import { pve, node as defaultNode, pveFor, type NodeConn } from "@/lib/proxmox";

export type DiskPoint = { time: number; disk: number | null; maxdisk: number | null };

const VALID_TF = ["hour", "day", "week", "month", "year"];

/**
 * Fetch the disk RRD series for a VM. `disk` = bytes used as seen by the
 * hypervisor, `maxdisk` = provisioned size. Note: for QEMU guests Proxmox
 * often cannot see in-guest usage, so `disk` may be 0/null — callers should
 * fall back to the provisioned/plan size for the "total".
 */
export async function serverDiskRrd(
  vmid: number,
  timeframe: string,
  conn?: NodeConn | null
): Promise<DiskPoint[]> {
  const tf = VALID_TF.includes(timeframe) ? timeframe : "day";
  let raw: any[];
  if (conn) {
    const client = pveFor(conn);
    raw = await client.get(`/nodes/${conn.pveNode}/qemu/${vmid}/rrddata`, {
      timeframe: tf,
      cf: "AVERAGE",
    });
  } else {
    raw = await pve.get(`/nodes/${defaultNode}/qemu/${vmid}/rrddata`, { timeframe: tf, cf: "AVERAGE" });
  }
  return (raw ?? [])
    .filter((r) => r && typeof r.time === "number")
    .map((r) => ({
      time: r.time,
      disk: typeof r.disk === "number" ? r.disk : null,
      maxdisk: typeof r.maxdisk === "number" ? r.maxdisk : null,
    }));
}

import { NextRequest, NextResponse } from "next/server";
import { db } from "@/lib/db";
import { currentUser } from "@/lib/auth";
import { serverDiskRrd } from "@/lib/server-metrics";

export const dynamic = "force-dynamic";

/** Read-only disk time-series for a server the current user owns. */
export async function GET(req: NextRequest, ctx: { params: Promise<{ id: string }> }) {
  const { id } = await ctx.params;
  const user = await currentUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });

  const tf = req.nextUrl.searchParams.get("tf") ?? "day";

  const server = await db.server.findUnique({
    where: { id },
    include: { node: true, plan: true },
  });
  if (!server || (server.userId !== user.id && user.role !== "ADMIN") || !server.vmid) {
    return NextResponse.json({ error: "not found" }, { status: 404 });
  }

  const planTotalBytes = server.plan.diskGB * 1024 ** 3;
  try {
    const conn: import("@/lib/proxmox").NodeConn | null = server.node
      ? {
          apiUrl: server.node.apiUrl,
          pveNode: server.node.pveNode,
          tokenId: server.node.tokenId,
          tokenSecret: server.node.tokenSecret,
        }
      : null;
    const data = await serverDiskRrd(server.vmid, tf, conn);
    return NextResponse.json({ data, planTotalBytes });
  } catch {
    // Hypervisor briefly unavailable — return an empty series, not a 500.
    return NextResponse.json({ data: [], planTotalBytes });
  }
}

