"use server";

import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser } from "./auth";

async function ownedServer(serverId: string) {
  const user = await requireUser();
  const server = await db.server.findUnique({ where: { id: serverId } });
  if (!server) throw new Error("Not found");
  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return { user, server };
}

/**
 * Set a customer-facing nickname (`Server.label`) shown as the primary name.
 * Passing an empty string clears the label (falls back to `Server.name`).
 * Validated (<= 40 chars, control chars stripped) and ownership-checked.
 */
export async function renameServer(
  serverId: string,
  label: string
): Promise<{ error?: string; label?: string | null }> {
  const { user } = await ownedServer(serverId);

  // Strip ASCII control characters, collapse whitespace, then trim.
  const clean = (label ?? "")
    .replace(/[\x00-\x1f\x7f]/g, "")
    .replace(/\s+/g, " ")
    .trim();
  if (clean.length > 40) return { error: "Name must be 40 characters or fewer." };
  const value = clean.length === 0 ? null : clean;

  await db.server.update({ where: { id: serverId }, data: { label: value } });
  await db.auditLog.create({
    data: {
      userId: user.id,
      action: "server.rename",
      detail: `${serverId} -> ${value ?? "(cleared)"}`,
    },
  });
  revalidatePath(`/dashboard/servers/${serverId}`);
  return { label: value };
}

"use server";

import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser } from "./auth";
import { registrarConfigured } from "./registrar";

/* ------------------------------------------------------------------ *
 * Minimal name.com v4 client (Basic auth), mirroring lib/registrar.ts.
 * These endpoints aren't exposed by the shared registrar helper, so we
 * call them directly here. All calls are guarded by registrarConfigured().
 * ------------------------------------------------------------------ */

function baseUrl(): string {
  return process.env.NAMECOM_ENV === "dev" ? "https://api.dev.name.com" : "https://api.name.com";
}

function authHeader(): string {
  const raw = `${process.env.NAMECOM_USERNAME}:${process.env.NAMECOM_TOKEN}`;
  return "Basic " + Buffer.from(raw).toString("base64");
}

async function nc(method: string, path: string, body?: unknown): Promise<any> {
  if (!registrarConfigured()) throw new Error("Domain registrar (name.com) is not configured");
  const res = await fetch(`${baseUrl()}${path}`, {
    method,
    headers: { Authorization: authHeader(), "Content-Type": "application/json" },
    body: body !== undefined ? JSON.stringify(body) : undefined,
    signal: AbortSignal.timeout(30_000),
  });
  const text = await res.text();
  let json: any = {};
  try {
    json = text ? JSON.parse(text) : {};
  } catch {
    /* non-JSON error body */
  }
  if (!res.ok) {
    const msg = json?.message || json?.details || text || `HTTP ${res.status}`;
    throw new Error(`name.com: ${msg}`);
  }
  return json;
}

function errMsg(e: unknown): string {
  return String(e instanceof Error ? e.message : e).slice(0, 200);
}

const HOST_RE = /^(?=.{1,253}$)([a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,}$/;

async function ownedDomain(domainId: string) {
  const user = await requireUser();
  const domain = await db.domain.findUnique({ where: { id: domainId } });
  if (!domain) throw new Error("Not found");
  if (domain.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return { user, domain };
}

/* ------------------------------------------------------------------ *
 * Nameservers
 * ------------------------------------------------------------------ */

export type NameserverResult = {
  error?: string;
  nameservers?: string[];
  registrarHit?: boolean;
  note?: string;
};

/**
 * Persist custom nameservers on the Domain and, when the domain is ACTIVE
 * and the registrar is configured, push them to name.com. Two or more
 * valid hostnames are required for a registrar update; an empty list clears
 * the override locally (name.com default NS remain untouched).
 */
export async function updateNameservers(
  domainId: string,
  nameservers: string[]
): Promise<NameserverResult> {
  const { user, domain } = await ownedDomain(domainId);

  const cleaned = (nameservers ?? [])
    .map((n) => n.trim().toLowerCase().replace(/\.$/, ""))
    .filter(Boolean);
  const unique = [...new Set(cleaned)];

  for (const ns of unique) {
    if (!HOST_RE.test(ns)) return { error: `Invalid nameserver hostname: ${ns}` };
  }
  if (unique.length > 13) return { error: "At most 13 nameservers are allowed." };
  if (unique.length === 1) return { error: "Provide at least two nameservers." };

  let registrarHit = false;
  let note: string | undefined;

  if (unique.length >= 2) {
    if (domain.status === "ACTIVE" && registrarConfigured()) {
      try {
        await nc("POST", `/v4/domains/${encodeURIComponent(domain.name)}:setNameservers`, {
          nameservers: unique,
        });
        registrarHit = true;
      } catch (e) {
        return { error: `Registrar rejected the update: ${errMsg(e)}` };
      }
    } else {
      note =
        "Saved. These will be applied at the registrar once the domain is active and the registrar is configured.";
    }
  }

  await db.domain.update({ where: { id: domainId }, data: { nameservers: unique } });
  await db.auditLog.create({
    data: {
      userId: user.id,
      action: "domain.nameservers",
      detail: `${domainId} -> [${unique.join(", ")}]${registrarHit ? " (registrar)" : ""}`,
    },
  });
  revalidatePath(`/dashboard/domains/${domainId}`);
  return { nameservers: unique, registrarHit, note };
}

/* ------------------------------------------------------------------ *
 * WHOIS privacy
 * ------------------------------------------------------------------ */

/**
 * Persist the WHOIS-privacy preference. name.com's privacy is a paid add-on
 * set at registration rather than a free live toggle, so this is persisted-
 * only: we record intent and surface a note. Ownership-checked.
 */
export async function setWhoisPrivacy(
  domainId: string,
  enabled: boolean
): Promise<{ error?: string; whoisPrivacy?: boolean; note?: string }> {
  const { user, domain } = await ownedDomain(domainId);

  await db.domain.update({ where: { id: domainId }, data: { whoisPrivacy: enabled } });
  await db.auditLog.create({
    data: {
      userId: user.id,
      action: "domain.whois_privacy",
      detail: `${domainId} -> ${enabled ? "on" : "off"}`,
    },
  });
  revalidatePath(`/dashboard/domains/${domainId}`);
  return {
    whoisPrivacy: enabled,
    note: `Preference saved (${enabled ? "on" : "off"}). WHOIS privacy at ${domain.registrar} is provisioned at registration — contact support to change it on a live domain.`,
  };
}

/* ------------------------------------------------------------------ *
 * Transfer out (registrar unlock + EPP / auth code)
 * ------------------------------------------------------------------ */

export type TransferResult = {
  error?: string;
  epp?: string;
  unlocked?: boolean;
  registrarHit?: boolean;
  note?: string;
};

/**
 * Prepare the domain for an outbound transfer: unlock the registrar lock and
 * retrieve the EPP/auth code from name.com, persisting it to `transferEpp`.
 * If the registrar isn't configured we can only surface a previously stored
 * code (or ask the customer to contact support). Ownership-checked.
 */
export async function requestTransferOut(domainId: string): Promise<TransferResult> {
  const { user, domain } = await ownedDomain(domainId);

  if (domain.status !== "ACTIVE") {
    return { error: "The domain must be active before it can be transferred out." };
  }

  let epp: string | null = domain.transferEpp ?? null;
  let unlocked = false;
  let registrarHit = false;

  if (registrarConfigured()) {
    // Unlock — some TLDs can't be unlocked via API; don't hard-fail on this.
    try {
      await nc("POST", `/v4/domains/${encodeURIComponent(domain.name)}:unlock`, {});
      unlocked = true;
    } catch {
      /* lock state may be managed manually for this TLD */
    }
    // Retrieve the auth code.
    try {
      const res = await nc("GET", `/v4/domains/${encodeURIComponent(domain.name)}:getAuthCode`);
      if (res?.authCode) {
        epp = String(res.authCode);
        registrarHit = true;
      }
    } catch (e) {
      if (!epp) return { error: `Could not retrieve the auth code: ${errMsg(e)}` };
    }
  }

  if (!epp) {
    return {
      error:
        "The transfer auth code isn't available yet — the registrar isn't connected. Please contact support to release this domain.",
    };
  }

  await db.domain.update({ where: { id: domainId }, data: { transferEpp: epp } });
  await db.auditLog.create({
    data: {
      userId: user.id,
      action: "domain.transfer_out",
      detail: `${domainId} unlock=${unlocked} registrar=${registrarHit}`,
    },
  });
  revalidatePath(`/dashboard/domains/${domainId}`);

  return {
    epp,
    unlocked,
    registrarHit,
    note: unlocked
      ? "Registrar lock released and auth code retrieved. Give this code to your new registrar to start the transfer."
      : "Auth code retrieved. If your new registrar reports the domain is locked, contact support to release the registrar lock.",
  };
}

"use client";

import { useCallback, useEffect, useState } from "react";
import { AreaChart, MeterBar } from "@/components/ui/charts";
import { fmtBytes } from "@/components/ui/primitives";

type Pt = { time: number; disk: number | null; maxdisk: number | null };

const TIMEFRAMES = [
  { key: "day", label: "24h" },
  { key: "week", label: "7d" },
  { key: "month", label: "30d" },
] as const;

const GB = 1024 ** 3;

function xLabelsFor(rows: Pt[], tf: string): string[] {
  if (rows.length < 2) return [];
  const n = 6;
  const labels: string[] = [];
  for (let i = 0; i < n; i++) {
    const idx = Math.round((i / (n - 1)) * (rows.length - 1));
    const d = new Date(rows[idx].time * 1000);
    labels.push(
      tf === "day"
        ? `${String(d.getHours()).padStart(2, "0")}:${String(d.getMinutes()).padStart(2, "0")}`
        : `${String(d.getMonth() + 1).padStart(2, "0")}/${String(d.getDate()).padStart(2, "0")}`
    );
  }
  return labels;
}

export function DiskUsageChart({
  serverId,
  planTotalGB,
  available = true,
}: {
  serverId: string;
  planTotalGB: number;
  available?: boolean;
}) {
  const [tf, setTf] = useState<string>("day");
  const [rows, setRows] = useState<Pt[] | null>(null);
  const [total, setTotal] = useState<number>(planTotalGB * GB);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(
    async (timeframe: string, quiet: boolean) => {
      if (!quiet) setRows(null);
      setError(null);
      try {
        const res = await fetch(`/api/servers/${serverId}/disk?tf=${timeframe}`, {
          cache: "no-store",
        });
        if (!res.ok) throw new Error("unavailable");
        const json: { data?: Pt[]; planTotalBytes?: number } = await res.json();
        const data = (json.data ?? []).filter((r) => r && typeof r.time === "number");
        setRows(data);
        // Prefer the provisioned size reported by the hypervisor; fall back to
        // the plan's disk size when the guest doesn't report maxdisk.
        const maxFromRrd = Math.max(0, ...data.map((r) => r.maxdisk ?? 0));
        setTotal(maxFromRrd > 0 ? maxFromRrd : (json.planTotalBytes ?? planTotalGB * GB));
      } catch {
        setError("Disk metrics are temporarily unavailable — the hypervisor may be busy.");
        setRows([]);
      }
    },
    [serverId, planTotalGB]
  );

  useEffect(() => {
    if (!available) return;
    void load(tf, false);
    const t = setInterval(() => void load(tf, true), 60_000);
    return () => clearInterval(t);
  }, [tf, load, available]);

  if (!available) {
    return (
      <p className="text-sm text-slate-400">
        Disk usage appears once the server is provisioned and running.
      </p>
    );
  }

  const loading = rows === null;
  const data = rows ?? [];
  const withUsage = data.filter((r) => typeof r.disk === "number" && (r.disk ?? 0) > 0);
  const hasUsage = withUsage.length > 0;
  const current = hasUsage ? (withUsage[withUsage.length - 1].disk ?? 0) : 0;
  const xLabels = xLabelsFor(data, tf);
  const totalGB = total / GB;
  const pct = total > 0 ? Math.min(100, (current / total) * 100) : 0;

  return (
    <div className="space-y-5">
      <div className="flex items-center justify-between">
        <p className="section-label">Disk usage over time</p>
        <div className="flex gap-1 rounded-xl border border-white/[0.08] bg-white/[0.03] p-1">
          {TIMEFRAMES.map((t) => (
            <button
              key={t.key}
              type="button"
              onClick={() => setTf(t.key)}
              className={`rounded-lg px-3 py-1 text-xs font-semibold transition-colors ${
                tf === t.key
                  ? "bg-gradient-to-r from-accent-blue to-brand-500 text-white"
                  : "text-slate-400 hover:text-white"
              }`}
            >
              {t.label}
            </button>
          ))}
        </div>
      </div>

      {/* Current usage meter */}
      <div>
        <div className="mb-1.5 flex justify-between text-sm">
          <span className="text-slate-400">Current</span>
          <span className="font-semibold">
            {hasUsage ? `${fmtBytes(current)} / ${fmtBytes(total)}` : `${totalGB.toFixed(0)} GB provisioned`}
          </span>
        </div>
        <MeterBar value={current} max={total || 1} />
        {hasUsage && (
          <p className="mt-1 text-xs text-slate-500">{pct.toFixed(1)}% used</p>
        )}
      </div>

      {error && (
        <div className="rounded-xl border border-amber-500/30 bg-amber-500/10 px-4 py-3 text-sm text-amber-300">
          {error}
        </div>
      )}

      {loading ? (
        <div className="skeleton h-52 w-full" />
      ) : !hasUsage ? (
        !error && (
          <p className="text-sm text-slate-500">
            The hypervisor isn&apos;t reporting in-guest disk usage for this VM yet, so only the
            provisioned size ({totalGB.toFixed(0)} GB) is shown. Historical usage appears here once
            the guest agent reports it.
          </p>
        )
      ) : (
        <AreaChart
          id={`disk-${tf}`}
          series={[
            {
              name: "Disk used",
              data: data.map((r) => (r.disk ?? 0) / GB),
              color: "#8a70fb",
            },
          ]}
          maxY={totalGB || undefined}
          yLabel={(v) => `${v.toFixed(0)} GB`}
          xLabels={xLabels}
        />
      )}
      <p className="text-xs text-slate-500">Refreshes automatically every 60 seconds.</p>
    </div>
  );
}

"use client";

import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { renameServer } from "@/lib/actions-server-extra";

export function ServerRename({
  serverId,
  label,
  fallback,
}: {
  serverId: string;
  label: string | null;
  fallback: string;
}) {
  const router = useRouter();
  const [editing, setEditing] = useState(false);
  const [value, setValue] = useState(label ?? "");
  const [error, setError] = useState<string | null>(null);
  const [pending, start] = useTransition();

  function save() {
    start(async () => {
      setError(null);
      const res = await renameServer(serverId, value);
      if (res?.error) setError(res.error);
      else {
        setEditing(false);
        router.refresh();
      }
    });
  }

  if (!editing) {
    return (
      <button
        type="button"
        onClick={() => {
          setValue(label ?? "");
          setError(null);
          setEditing(true);
        }}
        className="btn-ghost px-2.5 py-1 text-xs"
        title="Rename this server"
      >
        Rename
      </button>
    );
  }

  return (
    <div className="flex flex-col gap-1">
      <div className="flex items-center gap-2">
        <input
          className="input h-9 w-52 text-sm"
          autoFocus
          maxLength={40}
          value={value}
          placeholder={fallback}
          spellCheck={false}
          onChange={(e) => setValue(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === "Enter") save();
            if (e.key === "Escape") setEditing(false);
          }}
        />
        <button className="btn-primary px-3 py-1.5 text-xs" disabled={pending} onClick={save}>
          {pending ? "Saving…" : "Save"}
        </button>
        <button
          className="btn-secondary px-3 py-1.5 text-xs"
          disabled={pending}
          onClick={() => setEditing(false)}
        >
          Cancel
        </button>
      </div>
      <p className="text-xs text-slate-500">
        Leave blank to reset to <span className="font-mono">{fallback}</span>. Max 40 characters.
      </p>
      {error && <p className="text-xs text-red-400">{error}</p>}
    </div>
  );
}

"use client";

import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import {
  updateNameservers,
  setWhoisPrivacy,
  requestTransferOut,
} from "@/lib/actions-domains-advanced";
import { Badge } from "@/components/ui/primitives";

function CopyButton({ text }: { text: string }) {
  const [copied, setCopied] = useState(false);
  return (
    <button
      type="button"
      className="btn-secondary px-2.5 py-1 text-xs"
      onClick={async () => {
        try {
          await navigator.clipboard.writeText(text);
          setCopied(true);
          setTimeout(() => setCopied(false), 1500);
        } catch {
          /* clipboard unavailable */
        }
      }}
    >
      {copied ? "Copied" : "Copy"}
    </button>
  );
}

/* ---------------- Nameservers ---------------- */

function NameserversSection({
  domainId,
  initial,
  active,
  registrarReady,
}: {
  domainId: string;
  initial: string[];
  active: boolean;
  registrarReady: boolean;
}) {
  const router = useRouter();
  const [list, setList] = useState<string[]>(initial.length ? initial : ["", ""]);
  const [error, setError] = useState<string | null>(null);
  const [note, setNote] = useState<string | null>(null);
  const [pending, start] = useTransition();

  const setAt = (i: number, v: string) =>
    setList((l) => l.map((x, j) => (j === i ? v : x)));
  const removeAt = (i: number) => setList((l) => l.filter((_, j) => j !== i));
  const add = () => setList((l) => (l.length >= 13 ? l : [...l, ""]));

  function save() {
    start(async () => {
      setError(null);
      setNote(null);
      const res = await updateNameservers(domainId, list);
      if (res?.error) setError(res.error);
      else {
        setList(res.nameservers && res.nameservers.length ? res.nameservers : ["", ""]);
        setNote(
          res.registrarHit
            ? "Nameservers updated at the registrar. Propagation can take up to 24 hours."
            : res.note ?? "Saved."
        );
        router.refresh();
      }
    });
  }

  return (
    <div className="card">
      <div className="mb-1 flex items-center justify-between">
        <h2 className="font-semibold">Nameservers</h2>
        {registrarReady ? (
          <Badge tone="brand">name.com</Badge>
        ) : (
          <Badge tone="slate">saved locally</Badge>
        )}
      </div>
      <p className="mb-4 text-sm text-slate-400">
        Point this domain at custom nameservers (e.g. another DNS host). Provide at least two.
        Setting custom nameservers moves DNS off name.com&apos;s servers.
      </p>

      <div className="space-y-2">
        {list.map((ns, i) => (
          <div key={i} className="flex items-center gap-2">
            <input
              className="input font-mono text-xs"
              placeholder={`ns${i + 1}.example.com`}
              value={ns}
              autoComplete="off"
              spellCheck={false}
              onChange={(e) => setAt(i, e.target.value)}
            />
            <button
              type="button"
              className="btn-secondary px-2.5 py-2 text-xs"
              title="Remove"
              disabled={list.length <= 1}
              onClick={() => removeAt(i)}
            >
              ✕
            </button>
          </div>
        ))}
      </div>

      <div className="mt-3 flex flex-wrap items-center justify-between gap-3">
        <button
          type="button"
          className="btn-ghost px-3 py-1.5 text-xs"
          disabled={list.length >= 13}
          onClick={add}
        >
          + Add nameserver
        </button>
        <button className="btn-primary" disabled={pending} onClick={save}>
          {pending ? "Saving…" : "Save nameservers"}
        </button>
      </div>

      {!active && (
        <p className="mt-3 text-xs text-slate-500">
          The domain isn&apos;t active yet — changes are saved and applied at the registrar once it
          activates.
        </p>
      )}
      {note && <p className="mt-3 text-sm text-emerald-400">{note}</p>}
      {error && <p className="mt-3 text-sm text-red-400">{error}</p>}
    </div>
  );
}

/* ---------------- WHOIS privacy ---------------- */

function WhoisPrivacySection({
  domainId,
  initial,
}: {
  domainId: string;
  initial: boolean;
}) {
  const router = useRouter();
  const [enabled, setEnabled] = useState(initial);
  const [note, setNote] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [pending, start] = useTransition();

  function toggle() {
    const next = !enabled;
    setEnabled(next); // optimistic
    start(async () => {
      setError(null);
      setNote(null);
      const res = await setWhoisPrivacy(domainId, next);
      if (res?.error) {
        setEnabled(!next);
        setError(res.error);
      } else {
        setNote(res.note ?? "Saved.");
        router.refresh();
      }
    });
  }

  return (
    <div className="card">
      <div className="mb-1 flex items-center justify-between">
        <h2 className="font-semibold">WHOIS privacy</h2>
        <button
          type="button"
          disabled={pending}
          onClick={toggle}
          title={enabled ? "Privacy on — click to turn off" : "Privacy off — click to turn on"}
          className={`relative h-5 w-9 cursor-pointer rounded-full transition-colors disabled:opacity-50 ${
            enabled ? "bg-gradient-to-r from-accent-blue to-brand-500" : "bg-white/10"
          }`}
        >
          <span
            className={`absolute top-0.5 h-4 w-4 rounded-full bg-white transition-all ${
              enabled ? "left-[18px]" : "left-0.5"
            }`}
          />
        </button>
      </div>
      <p className="text-sm text-slate-400">
        When on, your personal contact details are hidden from the public WHOIS directory and
        replaced with privacy-protection contacts.
      </p>
      <p className="mt-2 text-xs text-slate-500">
        Currently <span className="font-medium text-slate-300">{enabled ? "on" : "off"}</span>.
      </p>
      {note && <p className="mt-3 text-sm text-emerald-400">{note}</p>}
      {error && <p className="mt-3 text-sm text-red-400">{error}</p>}
    </div>
  );
}

/* ---------------- Transfer out ---------------- */

function TransferSection({
  domainId,
  active,
  hasEpp,
}: {
  domainId: string;
  active: boolean;
  hasEpp: boolean;
}) {
  const router = useRouter();
  const [epp, setEpp] = useState<string | null>(null);
  const [note, setNote] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [pending, start] = useTransition();

  function reveal() {
    start(async () => {
      setError(null);
      setNote(null);
      const res = await requestTransferOut(domainId);
      if (res?.error) setError(res.error);
      else {
        if (res.epp) setEpp(res.epp);
        setNote(res.note ?? null);
        router.refresh();
      }
    });
  }

  return (
    <div className="card">
      <h2 className="mb-1 font-semibold">Transfer out</h2>
      <p className="text-sm text-slate-400">
        Moving to another registrar? Release the registrar lock and reveal the EPP / auth code below,
        then give it to your new registrar to authorize the transfer.
      </p>

      <div className="mt-4">
        {active ? (
          <button className="btn-secondary" disabled={pending} onClick={reveal}>
            {pending ? "Contacting registrar…" : hasEpp || epp ? "Re-reveal auth code" : "Unlock & reveal auth code"}
          </button>
        ) : (
          <Badge tone="slate">available once the domain is active</Badge>
        )}
      </div>

      {epp && (
        <div className="mt-4 rounded-xl border border-white/[0.08] bg-navy-950/60 p-3">
          <p className="mb-1.5 text-xs text-slate-400">EPP / auth code</p>
          <div className="flex items-center gap-2">
            <code className="flex-1 break-all rounded-lg border border-white/10 bg-black/30 px-2.5 py-1.5 font-mono text-xs">
              {epp}
            </code>
            <CopyButton text={epp} />
          </div>
        </div>
      )}

      {note && <p className="mt-3 text-sm text-emerald-300">{note}</p>}
      {error && <p className="mt-3 text-sm text-red-400">{error}</p>}
      <p className="mt-3 text-xs text-slate-500">
        After a transfer completes at the new registrar, this domain will stop being managed here.
      </p>
    </div>
  );
}

/* ---------------- Wrapper ---------------- */

export function DomainAdvanced({
  domainId,
  status,
  nameservers,
  whoisPrivacy,
  hasEpp,
  registrarReady,
}: {
  domainId: string;
  status: string;
  nameservers: string[];
  whoisPrivacy: boolean;
  hasEpp: boolean;
  registrarReady: boolean;
}) {
  const active = status === "ACTIVE";
  return (
    <div className="grid gap-6 lg:grid-cols-2">
      <NameserversSection
        domainId={domainId}
        initial={nameservers}
        active={active}
        registrarReady={registrarReady}
      />
      <WhoisPrivacySection domainId={domainId} initial={whoisPrivacy} />
      <div className="lg:col-span-2">
        <TransferSection domainId={domainId} active={active} hasEpp={hasEpp} />
      </div>
    </div>
  );
}

